actions.script:
def _o = ec.user.getPreference('ACTIVE_ORGANIZATION'); def _can = false
try { if (ec.user.isInGroup("ADMIN")) _can = true else { def _z = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }; _can = !(_z.size()==1 && _z.contains("ZENITH_CASHIER")) } } catch (Exception e) {}
if (_can && _o && _o != '_NA_') {
    if (ec.context.dd == 'home') ec.entity.find("zenith.erp.pos.OrgDashboardDefault").condition("organizationPartyId", _o).deleteAll()
    else ec.entity.makeValue("zenith.erp.pos.OrgDashboardDefault").set("organizationPartyId", _o).set("dashboardKey", "pos").createOrUpdate()
}

            dashboardOrgId = posOrganizationPartyId ?: '__NONE__'
            def userZone = ec.user.timeZone
            def sdf = new java.text.SimpleDateFormat("yyyy-MM-dd"); sdf.setTimeZone(userZone)
            def now = ec.user.nowTimestamp
            def todayStr = sdf.format(now)
            dateError = ''
            try {
                def fromDate = java.time.LocalDate.parse((dashDate ?: todayStr).toString())
                def toDate = java.time.LocalDate.parse((dashDateTo ?: fromDate.toString()).toString())
                if (fromDate.year < 1 || fromDate.year > 9999 || toDate.year < 1 || toDate.year > 9999) throw new java.time.DateTimeException('Unsupported date')
                if (toDate.isBefore(fromDate)) { def swap = fromDate; fromDate = toDate; toDate = swap }
                dashDate = fromDate.toString(); dashDateTo = toDate.toString()
            } catch (java.time.DateTimeException e) {
                dashDate = todayStr; dashDateTo = todayStr
                dateError = 'Enter valid From and To dates. Showing today.'
            }
            chartMode = ['hourly', 'daily', 'weekly', 'monthly'].contains(chartMode) ? chartMode : 'hourly'
            if (!dashLoc) dashLoc = ''

            def dayStart = ec.l10n.parseTimestamp(dashDate + ' 00:00:00', 'yyyy-MM-dd HH:mm:ss')
            def nextDay = java.time.LocalDate.parse(dashDateTo).plusDays(1)
            def dayEnd = new java.sql.Timestamp(ec.l10n.parseTimestamp(nextDay.toString() + ' 00:00:00', 'yyyy-MM-dd HH:mm:ss').time - 1)

            // Preset range anchors (each ends today)
            // Match weekly chart buckets; the server locale must not make Sunday "Today".
            def weekStartStr = java.time.LocalDate.parse(todayStr)
                .with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY)).toString()
            def _cm = java.util.Calendar.getInstance(userZone); _cm.setTime(now); _cm.set(java.util.Calendar.DAY_OF_MONTH, 1)
            def monthStartStr = sdf.format(_cm.getTime())
            def _c30 = java.util.Calendar.getInstance(userZone); _c30.setTime(now); _c30.add(java.util.Calendar.DAY_OF_MONTH, -29)
            def last30Str = sdf.format(_c30.getTime())
            def _dwYcal = java.util.Calendar.getInstance(userZone); _dwYcal.setTime(now); _dwYcal.set(java.util.Calendar.MONTH,0); _dwYcal.set(java.util.Calendar.DAY_OF_MONTH,1)
            def yearStartStr = sdf.format(_dwYcal.getTime())

            // active-preset detection (for chip highlight) + preset link URLs (relative query preserves the screen path)
            presetActive = 'custom'
            if (dashDateTo == todayStr) {
                if (dashDate == todayStr) presetActive = 'today'
                else if (dashDate == weekStartStr) presetActive = 'week'
                else if (dashDate == monthStartStr) presetActive = 'month'
                else if (dashDate == last30Str) presetActive = 'last30'
                else if (dashDate == yearStartStr) presetActive = 'year'
            }
            urlToday = "?dashDate=" + todayStr + "&dashDateTo=" + todayStr
            urlWeek  = "?dashDate=" + weekStartStr + "&dashDateTo=" + todayStr
            urlMonth = "?dashDate=" + monthStartStr + "&dashDateTo=" + todayStr
            url30    = "?dashDate=" + last30Str + "&dashDateTo=" + todayStr
            urlYear  = "?dashDate=" + yearStartStr + "&dashDateTo=" + todayStr
            urlSettings = "?dashDate=" + dashDate + "&dashDateTo=" + dashDateTo + (dashLoc ? "&dashLoc="+dashLoc : "") + "&chartMode=" + chartMode + "&showSettings=" + ((showSettings ?: '') == '1' ? '0' : '1')
            // ZE-DATEWISE: "Date-wise" custom-range tab -> force custom mode so only Date-wise highlights; reveal From/To
            if ((dateMode ?: '') == 'custom') presetActive = 'custom'
            showCustom = (((dateMode ?: '') == 'custom'))
            urlCustom = "?dateMode=custom&dashDate=" + dashDate + "&dashDateTo=" + dashDateTo + (dashLoc ? "&dashLoc="+dashLoc : "")

            if (dashDate == dashDateTo) {
                displayDate = new java.text.SimpleDateFormat("dd MMM yyyy, EEEE").format(java.sql.Date.valueOf(dashDate))
            } else {
                def _f1 = new java.text.SimpleDateFormat("dd MMM")
                def _f2 = new java.text.SimpleDateFormat("dd MMM yyyy")
                displayDate = _f1.format(java.sql.Date.valueOf(dashDate)) + " – " + _f2.format(java.sql.Date.valueOf(dashDateTo))
            }
            def rangeStart = java.sql.Date.valueOf(dashDate)
            def rangeEnd = java.sql.Date.valueOf(dashDateTo)
            def rangeShort = new java.text.SimpleDateFormat("dd MMM")
            def rangeLong = new java.text.SimpleDateFormat("dd MMM yyyy")
            rangeDisplay = (dashDate.substring(0, 4) == dashDateTo.substring(0, 4) ? rangeShort : rangeLong).format(rangeStart) + " – " + rangeLong.format(rangeEnd)

            // ZE-DASH-04 (Owner View): mode-adaptive location filter — MUST be computed BEFORE the entity-finds
            // below (which read _locSessionIds). Locations = the tenant's retail-store FACILITIES (branch/Owner-View)
            // when it runs 2+ stores, else its TERMINALS/counters (multi-counter). Hidden for a single location.
            // Transactions link via sessionId -> PosSession.terminalId -> Terminal.facilityId.
            def _org = dashboardOrgId
            // ZE-SHOP: the global shop switcher (ACTIVE_SHOP) drives this dashboard's store-mode filter unless the
            // user picked a specific location chip on THIS page (explicit dashLoc always wins).
            if (!dashLoc) { try { def _ass = ec.service.sync().name("zenith.base.ShopServices.get#ActiveShopScope").call(); if (_ass?.activeShopId) dashLoc = _ass.activeShopId } catch (Exception _ge) {} }
            locMode = 'none'; locOptions = []; _locSessionIds = dashLoc ? ['__NONE__'] : null
            try {
                if (_org && _org != '_NA_') {
                    def _terms = ec.entity.find("zenith.erp.pos.PosTerminal").condition("organizationPartyId", _org).list()
                    if (_terms) {
                        def _facIds = _terms.collect { it.facilityId }.findAll { it }.unique()
                        def _stores = _facIds ? ec.entity.find("mantle.facility.Facility").condition("facilityId","in",_facIds).condition("ownerPartyId",dashboardOrgId).condition("facilityTypeEnumId","FcTpRetailStore").list() : []
                        def _locTermIds = null
                        if (_stores.size() >= 2) {
                            locMode = 'store'
                            _stores.sort { it.facilityName }.each { f -> locOptions.add([id:f.facilityId, name:f.facilityName, url:"?dashDate="+dashDate+"&dashDateTo="+dashDateTo+"&dashLoc="+f.facilityId]) }
                            if (dashLoc) _locTermIds = _terms.findAll { it.facilityId == dashLoc }.collect { it.terminalId }
                        } else if (_terms.size() >= 2) {
                            locMode = 'counter'
                            _terms.sort { (it.terminalName ?: it.terminalId) }.each { t -> locOptions.add([id:t.terminalId, name:(t.terminalName ?: t.terminalId), url:"?dashDate="+dashDate+"&dashDateTo="+dashDateTo+"&dashLoc="+t.terminalId]) }
                            if (dashLoc) _locTermIds = [dashLoc]
                        }
                        if (dashLoc) {
                            _locTermIds = _terms.findAll { it.facilityId == dashLoc || it.terminalId == dashLoc }.collect { it.terminalId }
                            def _ss = _locTermIds ? ec.entity.find("zenith.erp.pos.PosSession").condition("organizationPartyId",dashboardOrgId).condition("terminalId","in",_locTermIds).list() : []
                            _locSessionIds = _ss ? _ss.collect { it.sessionId }.unique() : ['__NONE__']
                        }
                    }
                }
            } catch (Exception e) { locMode = 'none'; _locSessionIds = dashLoc ? ['__NONE__'] : null }
            urlLocAll = "?dashDate="+dashDate+"&dashDateTo="+dashDateTo
            locName = 'All ' + (locMode=='store' ? 'Shops' : 'Counters')
            if (dashLoc) { def _o = locOptions.find { it.id == dashLoc }; if (_o) locName = _o.name }
            if (dashLoc) { urlYear += '&dashLoc=' + java.net.URLEncoder.encode(dashLoc.toString(), 'UTF-8'); urlToday += "&dashLoc="+dashLoc; urlWeek += "&dashLoc="+dashLoc; urlMonth += "&dashLoc="+dashLoc; url30 += "&dashLoc="+dashLoc }
            def chartQuery = '&chartMode=' + chartMode
            urlToday += chartQuery; urlWeek += chartQuery; urlMonth += chartQuery; url30 += chartQuery; urlYear += chartQuery; urlSettings += chartQuery; urlCustom += chartQuery; urlLocAll += chartQuery
            locOptions.each { it.url += chartQuery }

            totalSales = completedTxns.sum { (it.payableAmount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
            totalOrders = completedTxns.size()
            avgOrderValue = totalOrders > 0 ? (totalSales / totalOrders).setScale(2, java.math.RoundingMode.HALF_UP) : BigDecimal.ZERO
            totalDiscount = completedTxns.sum { (it.discountTotal ?: 0) as BigDecimal } ?: BigDecimal.ZERO
            totalTax = completedTxns.sum { (it.totalTaxAmount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
            cancelledBills = voidedTxns.size()
            cancelledAmount = voidedTxns.sum { (it.payableAmount ?: 0) as BigDecimal } ?: BigDecimal.ZERO

            txnIds = completedTxns.collect { it.transactionId }

            // Payment breakdown
            def allPayments = txnIds ? ec.entity.find("zenith.erp.pos.PosPayment")
                .condition("transactionId", "in", txnIds).list() : []

            def pmColorMap = [UPI:'#7C3AED', Card:'#2563EB', Cash:'#F59E0B', Wallet:'#60A5FA', BankTransfer:'#60A5FA', Cheque:'#9CA3AF', Other:'#9CA3AF']
            def paymentTotals = new LinkedHashMap()
            allPayments.each { p ->
                def method = p.paymentMethod ?: 'Other'
                paymentTotals[method] = (paymentTotals[method] ?: BigDecimal.ZERO) + ((p.amount ?: 0) as BigDecimal)
            }
            paymentBars = []
            def totalPaymentAmt = paymentTotals.values().sum() ?: BigDecimal.ONE
            // biggest tender first (matches the mockup's legend order)
            def _pmSorted = paymentTotals.entrySet().sort { -(it.value as BigDecimal) }
            def _cumPct = 0.0
            def _donutSegs = new StringBuilder()
            _pmSorted.each { e ->
                def method = e.key; def amt = e.value as BigDecimal
                def pctExact = totalPaymentAmt > 0 ? (amt * 100.0 / totalPaymentAmt) : 0.0
                def pct = Math.round(pctExact.doubleValue()) as int
                def col = pmColorMap[method] ?: '#9CA3AF'
                paymentBars.add([method: method, amount: zinr.inr(ec.l10n.format(amt, '#,##0.00')), pct: pct, color: col])
                _donutSegs.append('<circle cx="70" cy="70" r="52" fill="none" stroke="'+col+'" stroke-width="17" pathLength="100" stroke-dasharray="'+String.format('%.2f',pctExact.doubleValue())+' 100" stroke-dashoffset="'+String.format('%.2f',-_cumPct)+'" transform="rotate(-90 70 70)" stroke-linecap="butt"/>')
                _cumPct += pctExact.doubleValue()
            }
            paymentDonutSvg = '<svg width="150" height="150" viewBox="0 0 140 140"><circle cx="70" cy="70" r="52" fill="none" stroke="#EDF0F5" stroke-width="17"/>' + _donutSegs.toString() + '</svg>'

            // Hourly sales breakdown
            def hourlySales = new BigDecimal[24]
            for (int i = 0; i < 24; i++) hourlySales[i] = BigDecimal.ZERO
            completedTxns.each { t ->
                if (t.entryDate) {
                    def cal = java.util.Calendar.getInstance(userZone)
                    cal.setTime(t.entryDate)
                    def hour = cal.get(java.util.Calendar.HOUR_OF_DAY)
                    hourlySales[hour] = hourlySales[hour] + ((t.payableAmount ?: 0) as BigDecimal)
                }
            }
            def maxH = hourlySales.max() ?: BigDecimal.ONE
            if (maxH == BigDecimal.ZERO) maxH = BigDecimal.ONE
            hourlyMax = maxH

            hourlyBars = []
            for (int h = 0; h < 24; h++) {
                def val = hourlySales[h]
                def pct = (val * 100 / maxH).intValue()
                if (pct < 3 && val > 0) pct = 3
                def label = ''
                if (val > 0) {
                    label = val >= 1000 ? zinr.inr(ec.l10n.format(val / 1000, '#0.#')) + 'k' : ec.l10n.format(val, '#,##0')
                }
                hourlyBars.add([hour: String.format("%d", h), pct: pct, label: label,
                    hasValue: val > BigDecimal.ZERO])
            }

            // Top selling products
            def barColors = ['#e91e63','#2196f3','#ff9800','#4caf50','#9c27b0','#00bcd4','#f44336','#3f51b5','#ff5722','#607d8b']
            topProductBars = []
            if (txnIds) {
                def itemList = ec.entity.find("zenith.erp.pos.PosTransactionItem")
                    .condition("transactionId", "in", txnIds).list()
                def productMap = [:]
                itemList.each { item ->
                    def pid = item.productName ?: item.productId
                    if (!productMap[pid]) productMap[pid] = [name: pid, orders: new java.util.HashSet(), total: BigDecimal.ZERO]
                    productMap[pid].orders.add(item.transactionId)
                    productMap[pid].total = productMap[pid].total + ((item.lineTotal ?: 0) as BigDecimal)
                }
                def sorted = productMap.values().sort { -(it.total as BigDecimal) }.take(5)
                def maxP = sorted ? (sorted[0].total as BigDecimal) : BigDecimal.ONE
                if (maxP == BigDecimal.ZERO) maxP = BigDecimal.ONE
                sorted.eachWithIndex { p, idx ->
                    def pct = (p.total * 100 / maxP).intValue()
                    topProductBars.add([name: p.name, total: '₹' + zinr.inr(ec.l10n.format(p.total, '#,##0.00')),
                        orders: p.orders.size(), pct: pct,
                        color: barColors[idx % barColors.size()]])
                }
            }

            lastBillNumber = completedTxns ? completedTxns.last().transactionNumber : '-'
            lastBillAmount = completedTxns ? zinr.inr(ec.l10n.format(completedTxns.last().payableAmount ?: 0, '#,##0.00')) : '0.00'

            // Expenses today
            todayExpenses = BigDecimal.ZERO
            try {
                def _eq = ec.entity.find("zenith.erp.pos.PosExpense").condition("organizationPartyId",dashboardOrgId)
                    .condition("expenseDate", "greater-equals", dayStart)
                    .condition("expenseDate", "less-equals", dayEnd)
                if (_locSessionIds) _eq.condition("sessionId", "in", _locSessionIds)   // ZE-SHOP: scope by selected shop
                def expList = _eq.list()
                todayExpenses = expList.sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
            } catch (Exception e) { /* entity may not exist yet */ }

            // Cash In/Out today
            todayCashIn = BigDecimal.ZERO
            todayCashOut = BigDecimal.ZERO
            try {
                def _cq = ec.entity.find("zenith.erp.pos.PosCashEntry").condition("organizationPartyId",dashboardOrgId)
                    .condition("entryDate", "greater-equals", dayStart)
                    .condition("entryDate", "less-equals", dayEnd)
                if (_locSessionIds) _cq.condition("sessionId", "in", _locSessionIds)   // ZE-SHOP: scope by selected shop
                def cashList = _cq.list()
                todayCashIn = cashList.findAll { it.entryType == 'CashIn' }.sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
                todayCashOut = cashList.findAll { it.entryType == 'CashOut' }.sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
            } catch (Exception e) { /* entity may not exist yet */ }

            // Stock alerts
            zeroStockCount = 0
            lowStockCount = 0
            try {
                def stockList = ec.entity.find("zenith.erp.inventory.ProductStockView").condition("ownerPartyId",dashboardOrgId).list()
                zeroStockCount = stockList.count { (it.totalQoh ?: 0) <= 0 }
                lowStockCount = stockList.count { def qoh = (it.totalQoh ?: 0) as BigDecimal; def rp = (it.reorderPoint ?: 0) as BigDecimal; qoh > 0 && rp > 0 && qoh <= rp }
            } catch (Exception e) { /* view may not exist */ }

            // Active KOTs
            activeKotCount = 0
            try {
                activeKotCount = ec.entity.find("zenith.erp.pos.KitchenOrderTicket").condition("organizationPartyId",dashboardOrgId)
                    .condition("statusId", "in", ["KotNew", "KotPreparing", "KotReady"]).count() as int
            } catch (Exception e) { /* entity may not exist */ }

            // Wastage today
            todayWastage = BigDecimal.ZERO
            try {
                def wList = ec.entity.find("zenith.erp.pos.PosStockWastage").condition("organizationPartyId",dashboardOrgId)
                    .condition("wastageDate", "greater-equals", dayStart)
                    .condition("wastageDate", "less-equals", dayEnd).list()
                todayWastage = wList.sum { (it.totalLoss ?: 0) as BigDecimal } ?: BigDecimal.ZERO
            } catch (Exception e) { /* entity may not exist */ }

            // Active sessions
            activeSessions = 0
            try {
                activeSessions = ec.entity.find("zenith.erp.pos.PosSession").condition("organizationPartyId",dashboardOrgId)
                    .condition("statusId", "PsOpen").count() as int
            } catch (Exception e) {}

            // ===== Business Health scorecard (ZcERP report v2.1.0) — a COMPOSITE 0-100 score computed from
            // REAL live data (never a fabricated number). Each of 5 metrics scores 0-100; a metric with no data
            // for the current context is marked "No data" and EXCLUDED from the average, so a zero-sales day
            // never fakes a low score. Sales & Cash Flow follow the selected date range; Receivables, Inventory
            // and GST are current snapshots. =====
            healthMetrics = []; healthScore = 0; healthLabel = '—'; healthHasData = false; healthColor = '#9e9e9e'
            try {
                def _orgH = dashboardOrgId
                def _nowH = ec.user.nowTimestamp
                def _pill = [good:['#DCFCE7','#059669'], warn:['#FEF3C7','#92400E'], bad:['#FEE2E2','#991B1B'], na:['#EEF0F5','#64748B']]
                def _col = { s -> s >= 80 ? 'good' : (s >= 55 ? 'warn' : 'bad') }
                def _add = { name, avail, score, status, ck -> def p = _pill[ck] ?: _pill.na; healthMetrics.add([name:name, avail:avail, score:score, status:status, pillBg:p[0], pillFg:p[1]]) }

                // prior equal-length period (for the Sales trend)
                def _pDays = (long)(((dayEnd.getTime() - dayStart.getTime()) / (1000L*60*60*24)) + 1)
                def _priorStart = new java.sql.Timestamp(dayStart.getTime() - _pDays*24L*60*60*1000)
                def _priorSales = BigDecimal.ZERO
                if (_orgH) {
                    def _pq = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", _orgH)
                        .condition("statusId","PtCompleted").condition("entryDate", org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO, _priorStart)
                        .condition("entryDate", org.moqui.entity.EntityCondition.LESS_THAN, dayStart)
                    if (_locSessionIds) _pq.condition("sessionId","in",_locSessionIds)  // only scope to a location when one is picked
                    _priorSales = _pq.list().sum { (it.payableAmount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
                }

                // 1) SALES — this period vs the prior equal-length period
                if (totalSales <= 0 && _priorSales <= 0) { _add('Sales', false, 0, 'No sales in range', 'na') }
                else {
                    double _g = _priorSales > 0 ? ((totalSales.doubleValue() - _priorSales.doubleValue()) * 100.0 / _priorSales.doubleValue()) : (totalSales > 0 ? 100.0 : -100.0)
                    def _s = _g >= 10 ? 95 : (_g >= 0 ? 80 : (_g >= -15 ? 60 : 35))
                    def _st = _g >= 10 ? 'Strong' : (_g >= 0 ? 'Good' : (_g >= -15 ? 'Fair' : 'Weak'))
                    def _gp = Math.round(_g)
                    _add('Sales', true, _s, _st + ' (' + (_gp >= 0 ? '+' : '') + _gp + '% vs prior)', _col(_s))
                }

                // 2) CASH FLOW — how much of sales is eaten by expenses + wastage (period)
                if (totalSales <= 0) { _add('Cash Flow', false, 0, 'No sales in range', 'na') }
                else {
                    def _out = ((todayExpenses ?: 0) as BigDecimal) + ((todayWastage ?: 0) as BigDecimal)
                    double _r = (_out.doubleValue() * 100.0 / totalSales.doubleValue())
                    def _s = _r < 5 ? 95 : (_r < 15 ? 80 : (_r < 30 ? 60 : 35))
                    def _st = _r < 5 ? 'Strong' : (_r < 15 ? 'Healthy' : (_r < 30 ? 'Watch' : 'Tight'))
                    _add('Cash Flow', true, _s, _st, _col(_s))
                }

                // reference: 90-day sales (denominator for the receivables ratio)
                def _c90 = java.util.Calendar.getInstance(); _c90.setTime(_nowH); _c90.add(java.util.Calendar.DAY_OF_MONTH, -90)
                def _ref90 = BigDecimal.ZERO
                if (_orgH) {
                    def _rq = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", _orgH)
                        .condition("statusId","PtCompleted").condition("entryDate", org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO, new java.sql.Timestamp(_c90.getTimeInMillis()))
                    if (_locSessionIds) _rq.condition("sessionId","in",_locSessionIds)
                    _ref90 = _rq.list().sum { (it.payableAmount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
                }

                // 3) RECEIVABLES — outstanding on credit bills (payable - paid), current
                def _creditOut = BigDecimal.ZERO
                if (_orgH) {
                    ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", _orgH)
                        .condition("isCredit","Y").condition("statusId","PtCompleted").list().each {
                            def _py = (it.payableAmount ?: 0) as BigDecimal; def _pd = (it.paidAmount ?: 0) as BigDecimal
                            if (_py > _pd) _creditOut += (_py - _pd)
                        }
                }
                if (_creditOut <= 0) { _add('Receivables', true, 100, 'Nothing outstanding', 'good') }
                else {
                    double _r = _ref90 > 0 ? (_creditOut.doubleValue() / _ref90.doubleValue()) : 1.0
                    def _s = _r < 0.02 ? 95 : (_r < 0.10 ? 80 : (_r < 0.25 ? 55 : 30))
                    def _st = _r < 0.02 ? 'Healthy' : (_r < 0.10 ? 'OK' : (_r < 0.25 ? 'Needs Attention' : 'High'))
                    _add('Receivables', true, _s, _st + ' (' + zinr.inr(ec.l10n.format(_creditOut, '#,##0')) + ' owed)', _col(_s))
                }

                // product-based snapshots (Inventory + GST)
                def _prodTot = _orgH ? ec.entity.find("mantle.product.Product").condition("ownerPartyId", _orgH).count() : 0
                if (_prodTot > 0) {
                    def _tracked = ec.entity.find("mantle.product.Product").condition("ownerPartyId", _orgH).condition("inventoryTracked","Y").count()
                    // 4) INVENTORY — stock health when tracked, else catalog readiness (priced items ready to sell)
                    if (_tracked >= 5) {
                        def _r = ((zeroStockCount + lowStockCount) * 1.0 / _tracked)
                        def _s = _r < 0.05 ? 95 : (_r < 0.15 ? 80 : (_r < 0.30 ? 55 : 30))
                        def _st = _r < 0.05 ? 'Healthy' : (_r < 0.15 ? 'Good' : (_r < 0.30 ? 'Needs Attention' : 'Low'))
                        _add('Inventory', true, _s, _st, _col(_s))
                    } else {
                        def _wp = ec.entity.find("mantle.product.Product").condition("ownerPartyId", _orgH).condition("mrpAmount", org.moqui.entity.EntityCondition.GREATER_THAN, 0G).count()
                        def _r = (_wp * 1.0 / _prodTot)
                        def _s = _r >= 0.95 ? 90 : (_r >= 0.80 ? 75 : (_r >= 0.50 ? 55 : 35))
                        def _st = _r >= 0.80 ? 'Catalog ready' : (_r >= 0.50 ? 'Some unpriced' : 'Many unpriced')
                        _add('Inventory', true, _s, _st, _col(_s))
                    }
                    // 5) GST — % of products with a GST slab / HSN / exempt flag
                    def _cf = ec.entity.conditionFactory
                    def _gstCond = _cf.makeCondition([
                        _cf.makeCondition("gstSlabId", org.moqui.entity.EntityCondition.IS_NOT_NULL, null),
                        _cf.makeCondition("isGstExempt", org.moqui.entity.EntityCondition.EQUALS, "Y"),
                        _cf.makeCondition("hsnCode", org.moqui.entity.EntityCondition.IS_NOT_NULL, null)
                    ], org.moqui.entity.EntityCondition.OR)
                    def _gstOk = ec.entity.find("mantle.product.Product").condition("ownerPartyId", _orgH).condition(_gstCond).count()
                    def _r = (_gstOk * 1.0 / _prodTot)
                    def _s = _r >= 0.95 ? 95 : (_r >= 0.80 ? 80 : (_r >= 0.50 ? 55 : 30))
                    def _st = _r >= 0.95 ? 'Compliant' : (_r >= 0.80 ? 'Mostly set' : (_r >= 0.50 ? 'Partial' : 'Needs setup'))
                    _add('GST', true, _s, _st, _col(_s))
                }

                def _avail = healthMetrics.findAll { it.avail }
                healthHasData = (_avail.size() > 0)
                healthScore = healthHasData ? (int) Math.round(_avail.sum { it.score } / _avail.size()) : 0
                healthLabel = healthScore >= 85 ? 'Excellent' : (healthScore >= 70 ? 'Good' : (healthScore >= 55 ? 'Fair' : 'Needs Work'))
                healthColor = healthScore >= 85 ? '#10B981' : (healthScore >= 70 ? '#059669' : (healthScore >= 55 ? '#D97706' : '#DC2626'))
            } catch (Exception e) { healthMetrics = []; healthScore = 0; healthLabel = '—'; healthHasData = false; healthColor = '#9e9e9e' }

            // SaaS module-access flags: hide ERP-module links not in the tenant's plan
            def _mods = context.saasAllowedModules
            boolean _allMod = (context.saasHasAllAccess == true) || (context.isSaasTenant != true)
            modSales = _allMod || (_mods != null && _mods.contains('sales'))
            modInventory = _allMod || (_mods != null && _mods.contains('inventory'))
            modContacts = _allMod || (_mods != null && _mods.contains('contacts'))
            modAccounting = _allMod || (_mods != null && _mods.contains('accounting'))
            modPurchase = _allMod || (_mods != null && _mods.contains('purchase'))

            // ZE-DASH-02/03: per-user switchable widgets + role-based defaults.
            // Role default applies ONLY when the user has never customized (pref == null). A POS-only cashier
            // (sole ZENITH_ role = ZENITH_CASHIER, not super-admin — same test the Terminal uses) gets a lean
            // view: Sales KPIs + Payment Breakdown; owners/managers/admin see everything.
            def _roleHidden = ''
            try {
                if (!ec.user.isInGroup("ADMIN")) {
                    def _zrp = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
                    if (_zrp.size() == 1 && _zrp.contains("ZENITH_CASHIER")) _roleHidden = 'opsKpi,hourly,products,health'
                }
            } catch (Exception e) {}
            def _prefRaw = ec.user.getPreference('POS_DASH_HIDDEN')
            def _hiddenPref = (_prefRaw != null) ? _prefRaw : _roleHidden
            def _hiddenSet = _hiddenPref.split(',').findAll { it }.toSet()
            showSalesKpi = !_hiddenSet.contains('salesKpi')
            showOpsKpi   = !_hiddenSet.contains('opsKpi')
            showHealth   = !_hiddenSet.contains('health')
            showHourly   = !_hiddenSet.contains('hourly')
            showPayments = !_hiddenSet.contains('payments')
            showProducts = !_hiddenSet.contains('products')
            w_salesKpi = showSalesKpi ? 'Y' : ''
            w_opsKpi   = showOpsKpi ? 'Y' : ''
            w_health   = showHealth ? 'Y' : ''
            w_hourly   = showHourly ? 'Y' : ''
            w_payments = showPayments ? 'Y' : ''
            w_products = showProducts ? 'Y' : ''
            // ZE-DASH-03: saved widget order (JS applies it on load + drag-to-reorder saves it back)
            dashOrderCsv = (ec.user.getPreference('POS_DASH_ORDER') ?: '')
            isDefaultDashPos = (ec.user.getPreference('DEFAULT_DASHBOARD') == 'pos')
            isTeamDefaultPos = false; canSetTeamPos = false
            try {
                def _o2 = ec.user.getPreference('ACTIVE_ORGANIZATION')
                if (ec.user.isInGroup("ADMIN")) canSetTeamPos = true
                else { def _z2 = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }; canSetTeamPos = !(_z2.size()==1 && _z2.contains("ZENITH_CASHIER")) }
                if (_o2 && _o2 != '_NA_') { def _oc2 = ec.entity.find("zenith.erp.pos.OrgDashboardDefault").condition("organizationPartyId", _o2).one(); isTeamDefaultPos = (_oc2?.dashboardKey == 'pos') }
            } catch (Exception e) {}

            // ===== ZE-DASH-MOCKUP: tinted stat cards with icons + delta-vs-prior-period (POS_Dashboard.jpeg) =====
            def _num2 = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00')) }
            def _intf = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0')) }
            deltaSuffix = (dashDate == dashDateTo) ? 'vs yesterday' : 'vs prev'

            // Edited (amended) bills in range
            editedBills = 0
            try { if (txnIds) editedBills = ec.entity.find("zenith.erp.pos.PosTransactionAmendment").condition("transactionId","in",txnIds).list().collect{ it.transactionId }.unique().size() } catch (Exception e) {}
            // Credit outstanding in range
            creditAmount = BigDecimal.ZERO; creditInvoices = 0
            completedTxns.findAll { it.isCredit == 'Y' }.each { def _py=(it.payableAmount?:0) as BigDecimal; def _pd=(it.paidAmount?:0) as BigDecimal; if (_py > _pd) { creditAmount += (_py - _pd); creditInvoices++ } }

            // Prior equal-length period (deltas)
            def _pDays = (long)(((dayEnd.getTime() - dayStart.getTime()) / (1000L*60*60*24)) + 1)
            def _prevStart = new java.sql.Timestamp(dayStart.getTime() - _pDays*24L*60*60*1000)
            def _prevEnd = new java.sql.Timestamp(dayStart.getTime() - 1000)
            def _pcq = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId",dashboardOrgId).condition("statusId","PtCompleted")
                .condition("entryDate", org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO, _prevStart)
                .condition("entryDate", org.moqui.entity.EntityCondition.LESS_THAN_EQUAL_TO, _prevEnd)
            if (_locSessionIds) _pcq.condition("sessionId","in",_locSessionIds)
            def _prevC = _pcq.list()
            def _pvq = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId",dashboardOrgId).condition("statusId","PtVoided")
                .condition("entryDate", org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO, _prevStart)
                .condition("entryDate", org.moqui.entity.EntityCondition.LESS_THAN_EQUAL_TO, _prevEnd)
            if (_locSessionIds) _pvq.condition("sessionId","in",_locSessionIds)
            def _prevSales = _prevC.sum { (it.payableAmount?:0) as BigDecimal } ?: 0.0G
            def _prevOrders = _prevC.size()
            def _prevAvg = _prevOrders>0 ? (_prevSales/_prevOrders) : 0.0G
            def _prevTax = _prevC.sum { (it.totalTaxAmount?:0) as BigDecimal } ?: 0.0G
            def _prevDisc = _prevC.sum { (it.discountTotal?:0) as BigDecimal } ?: 0.0G
            def _prevCanc = _pvq.list().size()
            def _prevEdit = 0
            try { def _pids = _prevC.collect{ it.transactionId }; if (_pids) _prevEdit = ec.entity.find("zenith.erp.pos.PosTransactionAmendment").condition("transactionId","in",_pids).list().collect{ it.transactionId }.unique().size() } catch (Exception e) {}

            def _pctd = { cur, prev -> def c=(cur?:0) as BigDecimal; def p=(prev?:0) as BigDecimal; p>0 ? ((c-p)*100/p) : (c>0 ? 100.0G : 0.0G) }
            def _dpct = { cur, prev -> def d=_pctd(cur,prev); (d>=0?'+':'') + ec.l10n.format(d, '#0.0') + '% ' + deltaSuffix }
            def _dabs = { cur, prev -> def d=((cur?:0) as int)-((prev?:0) as int); (d>=0?'+':'') + d + ' ' + deltaSuffix }
            def _up='#059669'; def _dn='#DC2626'; def _c={ d -> d >= 0 ? _up : _dn }
            def _ic = { d -> '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+d+'</svg>' }
            def _CART=_ic('<circle cx="8" cy="21" r="1"/><circle cx="19" cy="21" r="1"/><path d="M2.05 2.05h2l2.66 12.42a2 2 0 0 0 2 1.58h9.78a2 2 0 0 0 1.95-1.57l1.65-7.43H5.12"/>')
            def _ZAP=_ic('<polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/>')
            def _PCT=_ic('<path d="M3.85 8.62a4 4 0 0 1 4.78-4.77 4 4 0 0 1 6.74 0 4 4 0 0 1 4.78 4.78 4 4 0 0 1 0 6.74 4 4 0 0 1-4.77 4.78 4 4 0 0 1-6.75 0 4 4 0 0 1-4.78-4.77 4 4 0 0 1 0-6.76Z"/><path d="m15 9-6 6"/><path d="M9 9h.01"/><path d="M15 15h.01"/>')
            def _TAG=_ic('<path d="M12.586 2.586A2 2 0 0 0 11.172 2H4a2 2 0 0 0-2 2v7.172a2 2 0 0 0 .586 1.414l8.704 8.704a2.426 2.426 0 0 0 3.42 0l6.58-6.58a2.426 2.426 0 0 0 0-3.42Z"/><circle cx="7.5" cy="7.5" r=".5" fill="currentColor"/>')
            def _XC=_ic('<circle cx="12" cy="12" r="10"/><path d="m15 9-6 6"/><path d="m9 9 6 6"/>')
            def _FT=_ic('<path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/><path d="M10 9H8"/><path d="M16 13H8"/><path d="M16 17H8"/>')

            primaryCards = [
              [val:'₹'+_num2(totalSales), label:'Total Sales', sub:(totalOrders+' Orders'), delta:_dpct(totalSales,_prevSales), dcol:_c(_pctd(totalSales,_prevSales)), icon:_CART, bg:'#ECFDF5', ac:'#059669', ib:'#D1FAE5'],
              [val:'₹'+_num2(avgOrderValue), label:'Avg. Ticket Size', sub:null, delta:_dpct(avgOrderValue,_prevAvg), dcol:_c(_pctd(avgOrderValue,_prevAvg)), icon:_ZAP, bg:'#F5F3FF', ac:'#7C3AED', ib:'#EDE9FE'],
              [val:'₹'+_num2(totalTax), label:'Collected Tax', sub:null, delta:_dpct(totalTax,_prevTax), dcol:_c(_pctd(totalTax,_prevTax)), icon:_PCT, bg:'#EFF6FF', ac:'#3B82F6', ib:'#DBEAFE'],
              [val:'₹'+_num2(totalDiscount), label:'Total Discounts', sub:null, delta:_dpct(totalDiscount,_prevDisc), dcol:_c(_pctd(totalDiscount,_prevDisc)), icon:_TAG, bg:'#FFFBEB', ac:'#D97706', ib:'#FEF3C7'],
              [val:cancelledBills.toString(), label:'Bills Cancelled', sub:null, delta:_dabs(cancelledBills,_prevCanc), dcol:((cancelledBills-_prevCanc)>0?_dn:_up), icon:_XC, bg:'#FEF2F2', ac:'#DC2626', ib:'#FEE2E2'],
              [val:editedBills.toString(), label:'Edited Bills', sub:null, delta:_dabs(editedBills,_prevEdit), dcol:((editedBills-_prevEdit)>0?_dn:_up), icon:_FT, bg:'#EFF6FF', ac:'#3B82F6', ib:'#DBEAFE']
            ]
            secondaryCards = [
              [val:'₹'+_num2(todayCashIn), label:'Cash In', sub:null, bg:'#ECFDF5', vc:'#059669'],
              [val:'₹'+_num2(todayCashOut), label:'Cash Out', sub:null, bg:'#FFFBEB', vc:'#D97706'],
              [val:'₹'+_num2(((todayExpenses?:0) as BigDecimal) + ((todayWastage?:0) as BigDecimal)), label:'Expenses / Wastages', sub:(_intf(todayExpenses)+' / '+_intf(todayWastage)), bg:'#EFF6FF', vc:'#111827'],
              [val:(lowStockCount+' / '+zeroStockCount), label:'Low / Out of Stock', sub:null, bg:'#F5F3FF', vc:'#6D28D9'],
              [val:'₹'+_num2(creditAmount), label:'Credit Amount', sub:(creditInvoices+' Invoices'), bg:'#EFF6FF', vc:'#2563EB']
            ]

            // Group completed sales in the user's timezone; include empty buckets in the selected range.
            def chartFrom = java.time.LocalDate.parse(dashDate)
            def chartTo = java.time.LocalDate.parse(dashDateTo)
            def bucketDate = { java.time.LocalDate d ->
                chartMode == 'monthly' ? d.withDayOfMonth(1) :
                    (chartMode == 'weekly' ? d.with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY)) : d)
            }
            def chartTotals = new LinkedHashMap()
            if (chartMode == 'hourly') {
                for (int h = 0; h < 24; h++) chartTotals[h] = hourlySales[h]
            } else {
                def cursor = bucketDate(chartFrom)
                while (!cursor.isAfter(chartTo)) {
                    chartTotals[cursor] = BigDecimal.ZERO
                    cursor = chartMode == 'monthly' ? cursor.plusMonths(1) : cursor.plusDays(chartMode == 'weekly' ? 7 : 1)
                }
                completedTxns.each { txn ->
                    if (txn.entryDate) {
                        def localDay = java.time.Instant.ofEpochMilli(txn.entryDate.time).atZone(userZone.toZoneId()).toLocalDate()
                        def key = bucketDate(localDay)
                        if (chartTotals.containsKey(key)) chartTotals[key] += ((txn.payableAmount ?: 0) as BigDecimal)
                    }
                }
            }
            def dayLabel = java.time.format.DateTimeFormatter.ofPattern('dd MMM', java.util.Locale.ENGLISH)
            def monthLabel = java.time.format.DateTimeFormatter.ofPattern('MMM yyyy', java.util.Locale.ENGLISH)
            chartBuckets = chartTotals.collect { key, amount ->
                def label = chartMode == 'hourly' ? ((key % 12 ?: 12).toString() + (key < 12 ? ' AM' : ' PM')) :
                    (chartMode == 'monthly' ? key.format(monthLabel) : (key.isBefore(chartFrom) ? chartFrom : key).format(dayLabel))
                def description = label
                if (chartMode == 'weekly') {
                    def last = key.plusDays(6).isAfter(chartTo) ? chartTo : key.plusDays(6)
                    description += ' – ' + last.format(dayLabel)
                }
                [label:label, description:description, amount:amount]
            }
            def chartMax = chartBuckets.collect { it.amount }.max() ?: BigDecimal.ONE
            if (chartMax <= 0) chartMax = BigDecimal.ONE
            // Plot exact totals rather than rounded hourly percentages.
            double _CW=680.0, _CH=210.0, _bx=38.0, _by=176.0
            double _plotW=_CW-_bx-10, _plotH=_by-16
            def _pts2 = []
            chartBuckets.eachWithIndex { bucket, index ->
                double x = _bx + (chartBuckets.size() == 1 ? _plotW / 2 : index * _plotW / (chartBuckets.size() - 1))
                double y = _by - (bucket.amount / chartMax).doubleValue() * _plotH
                _pts2.add([x:x, y:y, bucket:bucket])
            }
            def _f = { double v -> String.format(java.util.Locale.ROOT, '%.1f', v) }
            // Smooth the hourly line without changing any actual sales values.
            def _curve = new StringBuilder('M'+_f(_pts2[0].x)+','+_f(_pts2[0].y))
            for (int i=0; i<_pts2.size()-1; i++) {
                def p0 = _pts2[Math.max(0,i-1)], p1 = _pts2[i], p2 = _pts2[i+1], p3 = _pts2[Math.min(_pts2.size()-1,i+2)]
                double c1x=p1.x+(p2.x-p0.x)/6.0, c1y=p1.y+(p2.y-p0.y)/6.0
                double c2x=p2.x-(p3.x-p1.x)/6.0, c2y=p2.y-(p3.y-p1.y)/6.0
                // Keep the smooth line between its real endpoints, including zero-sales buckets.
                double lowY=Math.min(p1.y,p2.y), highY=Math.max(p1.y,p2.y)
                c1y=Math.max(lowY,Math.min(highY,c1y)); c2y=Math.max(lowY,Math.min(highY,c2y))
                _curve.append(' C'+_f(c1x)+','+_f(c1y)+' '+_f(c2x)+','+_f(c2y)+' '+_f(p2.x)+','+_f(p2.y))
            }
            def _lineStr = _curve.toString()
            def _areaStr = _lineStr+' L'+_f(_pts2[-1].x)+','+_f(_by)+' L'+_f(_pts2[0].x)+','+_f(_by)+' Z'
            def _dots = new StringBuilder(); _pts2.each { point ->
                if (point.bucket.amount != 0 || chartBuckets.size() == 1) _dots.append('<circle cx="'+_f(point.x)+'" cy="'+_f(point.y)+'" r="3" fill="#3B82F6"><title>'+point.bucket.description+': ₹'+_num2(point.bucket.amount)+'</title></circle>')
            }
            def _grid = new StringBuilder()
            for (int t=0; t<=4; t++) { double frac=t/4.0; double yv=_by-frac*_plotH; def val=chartMax*frac
                def lbl = val >= 1000 ? (String.format(java.util.Locale.ROOT, '%.0f',(val/1000).doubleValue())+'K') : String.format(java.util.Locale.ROOT, chartMax < 4 ? '%.2f' : '%.0f',val.doubleValue())
                _grid.append('<line x1="'+_f(_bx)+'" y1="'+_f(yv)+'" x2="'+_f(_CW-10)+'" y2="'+_f(yv)+'" stroke="#F1F5F9" stroke-width="1"/>')
                _grid.append('<text x="'+_f(_bx-6)+'" y="'+_f(yv+3)+'" font-size="9" fill="#9CA3AF" text-anchor="end">'+lbl+'</text>') }
            def _xl = new StringBuilder()
            def visibleTicks = Math.min(chartMode == 'monthly' ? 12 : 8, chartBuckets.size())
            def tickIndexes = chartMode == 'hourly' ? (0..<24).findAll { it % 2 == 0 } :
                (0..<visibleTicks).collect { tick -> chartBuckets.size() == 1 ? 0 : Math.round(tick * (chartBuckets.size() - 1) / (visibleTicks - 1.0)) as int }.unique()
            tickIndexes.each { index ->
                def point = _pts2[index]
                def anchor = chartMode != 'hourly' && chartBuckets.size() > 1 ? (index == 0 ? 'start' : (index == chartBuckets.size()-1 ? 'end' : 'middle')) : 'middle'
                _xl.append('<text class="pos-chart-x-label" x="'+_f(point.x)+'" y="'+_f(_by+15)+'" font-size="9" fill="#9CA3AF" text-anchor="'+anchor+'">'+point.bucket.label+'</text>')
            }
            salesLineSvg = '<svg role="img" aria-label="'+chartMode.capitalize()+' sales from '+dashDate+' to '+dashDateTo+'" data-chart-mode="'+chartMode+'" viewBox="0 0 '+((int)_CW)+' '+((int)_CH)+'" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;min-width:560px">'+
                '<defs><linearGradient id="posDashSalesFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#57A9F5" stop-opacity=".25"/><stop offset="100%" stop-color="#57A9F5" stop-opacity=".02"/></linearGradient></defs>'+
                _grid.toString()+'<path d="'+_areaStr+'" fill="url(#posDashSalesFill)"/>'+
                '<path d="'+_lineStr+'" fill="none" stroke="#57A9F5" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>'+
                _dots.toString()+_xl.toString()+'</svg>'

            // ===== Recent transactions (last 5) — for the mockup's Recent Transactions table =====
            def _payByTxn = [:]
            allPayments.each { p -> def mm=_payByTxn.get(p.transactionId,[:]); def k=(p.paymentMethod?:'Other'); mm[k]=(mm[k]?:0.0G)+((p.amount?:0) as BigDecimal) }
            def _tf3 = new java.text.SimpleDateFormat("hh:mm a")
            def _pmPill = [UPI:['#F5F3FF','#7C3AED'], Cash:['#ECFDF5','#059669'], Card:['#EFF6FF','#2563EB']]
            recentTxns = []
            ((completedTxns as List).reverse().take(5)).each { t ->
                def _mm = _payByTxn[t.transactionId]; def _pm = _mm ? _mm.entrySet().max{ it.value }.key : '—'
                def _pmc = _pmPill[_pm] ?: ['#F1F5F9','#475569']
                def _st = (t.isCredit=='Y' && ((t.payableAmount?:0) as BigDecimal) > ((t.paidAmount?:0) as BigDecimal)) ? 'Pending' : 'Paid'
                def _stc = (_st=='Paid') ? ['#ECFDF5','#059669'] : ['#FFFBEB','#D97706']
                recentTxns.add([time:_tf3.format(t.entryDate), bill:(t.transactionNumber ?: t.transactionId).toString(),
                    cust:(t.customerName ?: 'Walk-in Customer'), amt:'₹'+zinr.inr(ec.l10n.format((t.payableAmount?:0) as BigDecimal,'#,##0.00')),
                    pm:_pm, pmBg:_pmc[0], pmFg:_pmc[1], status:_st, stBg:_stc[0], stFg:_stc[1]])
            }
